func signalWatchProcessGroup(pid int, signal syscall.Signal) error {
	if group, err := syscall.Getpgid(pid); err == nil && group == pid {
		return syscall.Kill(-pid, signal)
	}
	return syscall.Kill(pid, signal)
}

